export function phoneTokens(text: string): number {
  if (!text) return 0
  let wide = 0
  for (let i = 0; i < text.length; i++) if (text.charCodeAt(i) > 127) wide++
  return Math.ceil((text.length - wide) / CHARS_PER_TOKEN + wide)
}
